components.UnifiedBrief:
function UnifiedBrief({profile,view,customer,filters,ai}){
  const [result,setResult]=useState(profile.combined),[busy,setBusy]=useState(false);
  async function generate(){setBusy(true);try{setResult(await api('/customer-intelligence/brief',{view,customer_id:customer,...filters,ai}));}catch(e){setResult({...profile.combined,source:'Deterministic explanation · '+e.message});}finally{setBusy(false);}}
  const offerView=view==='CROSS_SELL'&&profile.offer;
  return <section className="panel insights" aria-busy={busy}><div className="panel-heading"><div className="insight-title"><Sparkles size={23}/><h2>{offerView?'Travel Insurance engagement brief':'AI-assisted retention explanation'}</h2><span className="pill">{ai?'AI assisted':'Business rules'}</span></div><button className="button primary" disabled={busy} onClick={generate}>{busy?<LoaderCircle className="spin" size={16}/>:<Sparkles size={16}/>} {busy?'Preparing brief…':'Generate engagement brief'}</button></div>
    <div className="insight-grid"><div><div className="eyebrow muted">{offerView?'CANDIDATE PRODUCT':'RETENTION ACTION'}</div><p className="finding">{offerView?'Travel Insurance · Human review required':result.finding}</p></div><div><div className="eyebrow muted">VERIFIED CUSTOMER EVIDENCE</div><ul>{result.ids.slice(0,3).map(i=><li key={i}>{result.facts[i]}</li>)}</ul></div><div><div className="eyebrow muted">{offerView?'ENGAGEMENT APPROACH':'RECOMMENDED RETENTION ACTION'}</div><p>{offerView?profile.offer.action:profile.retention.action}</p></div></div>
    <p className="insight-source" role="status">{busy?'Reviewing the supporting evidence…':sourceLabel(result.source)} · Human review required. No customer message is sent.</p>
    <details><summary>Supporting evidence for this brief<ChevronDown size={16}/></summary><ul>{result.facts.map((fact,i)=><li key={i}>{fact}</li>)}</ul></details>
  </section>;
}

components.CustomerSegmentation:
function CustomerSegmentation({segments,field,title}){
  const groups=customerSegments(segments,field),maximum=Math.max(1,...groups.map(group=>group.count));
  return <Panel title={title} subtitle="Full portfolio · Existing customer segments">
    {!groups.length?<Empty>No segment breakdown is available.</Empty>:<div className="customer-segmentation">{groups.map(group=><div className="customer-segment-row" key={group.label}><span>{field==='RETENTION_RISK_BAND'?<Badge value={group.label}/>:group.label}</span><div className="customer-segment-track" aria-hidden="true"><i style={{width:`${100*group.count/maximum}%`}}/></div><b>{number(group.count)}</b></div>)}</div>}
  </Panel>;
}

